mapper.select:
SELECT A.*, B.* FROM ( SELECT tt1.rnum no, tt1.content_id, tt1.genre_id, tt1.genre_name, tt1.external_genre_id FROM ( SELECT ROWNUM rnum, t1.* FROM ( SELECT cg.content_id, cg.genre_id, g.name AS genre_name, g.external_genre_id FROM content_genre cg JOIN genre g ON cg.genre_id = g.genre_id
ORDER BY cg.content_id ASC, cg.genre_id ASC ) t1 WHERE ROWNUM <= (#{pageSize} * (#{pageNo} - 1) + #{pageSize}) ) tt1 WHERE rnum >= (#{pageSize} * (#{pageNo} - 1) + 1) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM content_genre cg
) B

mapper.insert:
INSERT INTO content_genre (
	content_id,
	genre_id
) VALUES (
	#{contentId},
	#{genreId}
)

mapper.update:
UPDATE content_genre
   SET genre_id = #{genreId}
 WHERE content_id = #{contentId}
   AND genre_id = #{genreId}

mapper.delete:
DELETE FROM content_genre
 WHERE content_id = #{contentId}
   AND genre_id = #{genreId}
